def transpose_records(records):
    keys = []
    for rec in records:
        for k in rec:
            if k not in keys:
                keys.append(k)
    if not keys:
        return []
    result = []
    for k in keys:
        col = [rec.get(k) for rec in records]
        result.append([k, col])
    return result
