def transpose_records(records):
    if not records:
        return []
    keys = []
    for rec in records:
        if rec:
            keys.extend(rec.keys())
    if not keys:
        return []
    seen = set()
    uniq_keys = []
    for k in keys:
        if k not in seen:
            seen.add(k)
            uniq_keys.append(k)
    result = []
    for k in uniq_keys:
        col = [rec.get(k) for rec in records]
        result.append([k, col])
